arguments.file_text:
@using sv_5c3e4b2c00ee455cadd1e10df9b5c54e.Services

<div class="message-area">
    <div class="message-area-header">
        <h4># @ChannelName</h4>
        <span class="channel-description">@ChannelDescription</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; }

    private bool _loadingMore;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        // Scroll-to-top pagination is handled via JS interop in the page.
        // This event fires on any scroll; the parent decides when to load more.
        if (HasMoreMessages && !_loadingMore)
        {
            _loadingMore = true;
            await OnLoadMore.InvokeAsync();
            _loadingMore = false;
        }
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #313338;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.message-area-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1.05rem;
    font-weight: 700;
}

.channel-description {
    color: #72767d;
    font-size: 0.8rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    color: #72767d;
    font-size: 0.8rem;
    padding: 12px;
}

@using sv_5c3e4b2c00ee455cadd1e10df9b5c54e.Services

<div class="thread-panel">
    <div class="thread-header">
        <h5>Thread</h5>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-messages">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="reply-header">
                        <span class="reply-author">@reply.Author</span>
                        <span class="reply-timestamp">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="reply-content">@reply.Content</div>
                </div>
            }
        </div>
    }

    <MessageInput Placeholder="Reply to thread…"
                  ButtonLabel="Reply"
                  OnSend="OnSendReply" />
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

